public class MVCPattern {
    static class Spell { String name; int power; }
    static class SpellView {
        void display(String name, int power) {
            System.out.println(name + " [" + power + " dmg]");
        }
    }
    static class SpellController {
        private Spell model; private SpellView view;
        SpellController(Spell m, SpellView v) { model=m; view=v; }
        void setName(String n) { model.name = n; }
        void setPower(int p) { model.power = p; }
        void updateView() { view.display(model.name, model.power); }
    }
    public static void main(String[] args) {
        Spell spell = new Spell();
        spell.name = "Fireball"; spell.power = 80;
        SpellController ctrl = new SpellController(spell, new SpellView());
        ctrl.updateView();
        ctrl.setPower(100);
        ctrl.updateView();
    }
}

