import java.util.*;

public class RepositoryPattern {
    interface WizardRepository {
        void save(String name, int level);
        Optional<Integer> findLevel(String name);
    }
    static class InMemoryWizardRepository implements WizardRepository {
        private Map<String, Integer> store = new HashMap<>();
        public void save(String name, int level) { store.put(name, level); }
        public Optional<Integer> findLevel(String name) { return Optional.ofNullable(store.get(name)); }
    }
    static class WizardService {
        private WizardRepository repo;
        WizardService(WizardRepository r) { repo = r; }
        void register(String name, int level) { repo.save(name, level); }
        String info(String name) {
            return repo.findLevel(name)
                .map(l -> name + " (Lv." + l + ")")
                .orElse(name + " not found");
        }
    }
    public static void main(String[] args) {
        WizardService svc = new WizardService(new InMemoryWizardRepository());
        svc.register("Merlin", 99);
        System.out.println(svc.info("Merlin"));
        System.out.println(svc.info("Gandalf"));
    }
}

