public class SOLIDPrinciples {
    interface Logger { void log(String msg); }
    static class ConsoleLogger implements Logger {
        public void log(String msg) { System.out.println("[LOG] " + msg); }
    }
    static class SilentLogger implements Logger {
        public void log(String msg) { /* silent */ }
    }
    static class SpellCaster {
        private Logger logger;
        SpellCaster(Logger l) { logger = l; }
        void cast(String spell) {
            logger.log("Casting: " + spell);
            System.out.println(spell + " cast!");
        }
    }
    public static void main(String[] args) {
        new SpellCaster(new ConsoleLogger()).cast("Fireball");
        new SpellCaster(new SilentLogger()).cast("IceBolt");
    }
}
